    "seamTimeoutMs": {
      "type": "number",
      "title": "Seam timeout (ms)",
      "description": "How long one raised seam tool may run before the compaction goes on without it. 0 uses 90000.",
      "default": 0
    },
    "abStockShare": {
      "type": "string",
      "title": "A/B stock share",
      "description": "The share left to the engine's own compaction, for comparison: of sessions for half the sessions, of compactions for the other half. 0.5 splits evenly. Empty is no split. Needs live on.",
      "default": ""
    },
    "subagents": {
      "type": "boolean",
      "title": "Answer subagent compactions",
      "description": "Off, a subagent's compaction is passed through with a row saying so. On, it is answered like any other."
