    "dev": {
      "type": "boolean",
      "title": "Measurement tools",
      "description": "Registers the four measurement tools."
    },
    "refresh": {
      "type": "boolean",
      "title": "Fallback handoff",
      "description": "Keeps a fallback handoff on disk for sessions a fork cannot serve (headless)."
    },
    "refreshMs": {
      "type": "number",
      "title": "Refresh gap (ms)",
      "description": "Shortest gap between two refreshes, and never sooner than 20 new messages. 0 uses 600000.",
      "default": 0
    }
  }
}

